from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import goodwill_credit
from ledgerly.errors import BillingError
from ledgerly.models import Invoice, LineItem

def inv(status="issued", total="50.00"):
    return Invoice("inv_1","cus_1",lines=[LineItem("Seat",1,Decimal(total))],status=status)

# basic
r = goodwill_credit(inv(), Decimal("5.00"), "late")
print(r, audit.events("goodwill_credit"))

# non-positive
for a in [Decimal("0"), Decimal("-1")]:
    try: goodwill_credit(inv(), a, "x")
    except BillingError as e: print("err", e.code)

# exceeds total
try: goodwill_credit(inv(), Decimal("50.01"), "x")
except BillingError as e: print("err", e.code)

# not issued
try: goodwill_credit(inv("draft"), Decimal("1"), "x")
except BillingError as e: print("err", e.code)

# approval threshold
try: goodwill_credit(inv(total="2000.00"), Decimal("1000.01"), "x")
except BillingError as e: print("err", e.code)
print(goodwill_credit(inv(total="2000.00"), Decimal("1000.00"), "x")["amount"])
print(goodwill_credit(inv(total="2000.00"), Decimal("1000.01"), "x", approved_by="mgr")["amount"])

# idempotency
audit.clear()
a = goodwill_credit(inv(), Decimal("5.00"), "late", idempotency_key="k1")
b = goodwill_credit(inv(), Decimal("5.00"), "late", idempotency_key="k1")
print(a==b, len(audit.events("goodwill_credit")))
